import SwiftUI
struct JafarCommandResultView: View { @ObservedObject var voice: VoiceSessionViewModel; var body: some View { VStack(alignment: .leading, spacing: 6) { if voice.isListening { Label("Слушаю…", systemImage: "waveform") }; if !voice.transcript.isEmpty { Text("Команда: \(voice.transcript)").font(.caption).foregroundStyle(.secondary) }; if !voice.response.isEmpty { Text(voice.response).font(.callout) }; if let error = voice.errorMessage { Label(error, systemImage: "exclamationmark.triangle").foregroundStyle(.orange).font(.caption) } }.accessibilityElement(children: .combine) } }
